r"""
Crescopus - November fixes

  1. No more stray "p" under the rich text boxes on the card editor.
  2. Image uploads (app image, photo, pictures in a pitch) now go through
     Crescopus, which checks you own the card and stores the image.
  3. CrescoLedger notice: shown once to each person (they must press
     "I understand"), plus a standing note on the ledger and updated Terms.
  4. Stronger CrescoGuide (AI) disclaimers: consent box, a note under every
     summary, the dispute guide, and the Terms.
  5. While writing the plan, each person's ticked Needs and Offers are shown;
     tap one to add it as a bullet. Matches are marked with a tick.
  6. A plan's first save is now version 1 (it used to jump to version 2).
  7. Sending a message confirms it was sent; unread checks made more robust.
  8. Only the Builder chooses the ledger currency.

HOW TO USE
  1. Save this file in your Crescopus project folder (next to wsgi.py).
  2. In PowerShell, in that folder, with your venv active:
         python apply_nov_fixes.py
  3. Run sql/migration_nov_fixes.sql in the Supabase SQL editor. Safe to re-run.
  4. Any file it replaces is copied first to _backup_apply_nov_fixes\.

It checks each file matches the version on GitHub first. If you've changed
one locally since your last push, it stops without writing anything.
Your .env is never read or changed.
"""
import base64, hashlib, os, shutil, sys

# (path, new content, sha256s of the versions it may replace)
FILES = [
    ('app/browse/routes.py', '', ['51c201a0f973737940db338f5a08732caf0d35fae24b4c4b2af8106cdea6e881']),
    ('app/ledger/routes.py', '', ['7a6afd444138d9c90239e1a882da3f2e21a2d8e181e1eca8374c97dfd79b211e']),
    ('app/partnerships/routes.py', '', ['c38493723ef4e291ebfa19373b3f2d9bbaf9f519fa907a84a2d6f2d724594049']),
    ('app/plans/routes.py', '', ['789c2c6a71711c6c8fa658f15f836435493d6c627915c62ae19bf439b44c56eb']),
    ('app/static/css/cresco-ui.css', '', ['a50b5dcf4440bf8ee265fb1726493ed9521d0014ccfef28bdf3845ea54f98b56']),
    ('app/static/js/image-uploader.js', '', ['946831422aae979bc661273049ee10d6233d96ee26630cab785d1c20ca23cabe']),
    ('app/static/js/pitch-editor.js', '', ['1ee0bf4aa9da8308f720811f3d56d0592af5d158626d4623677b83106e731f82']),
    ('app/static/js/plan-editor.js', '', ['27d24981337a42f409e667ef97100e8ccfa464f613efeda25ae0455c7c48b5ee']),
    ('app/templates/base.html', '', ['899584fca4a3e378f9c2541eb4d0ffeb6f9f9eb431c7efed362960a8d6d4aa37']),
    ('app/templates/ledger/_notice.html', '', []),
    ('app/templates/ledger/dispute_new.html', '', ['c7a54d5ece08df3a80c0c04d98245c151c7d4ca005de9aa4f80c954532581d72']),
    ('app/templates/ledger/dispute_view.html', '', ['a8bca3030abfcf1060effb7491c0791d061531bc3391974cae1e6dc6d3ab5a92']),
    ('app/templates/ledger/entry_form.html', '', ['538e328a2739d1cc6b26982a421bf29a03157a116b1b06cbd1ee8c32d442eb7f']),
    ('app/templates/ledger/view.html', '', ['5049ad3a385d32c55cfa7ccc8da615f6a0bd817990f3abd816e7c3c3506ac425']),
    ('app/templates/plans/edit.html', '', ['1a3e28c688cf9b29a7d6193f17b866728797c271483b0c38b43c0f14431a3af4']),
    ('app/utils.py', '', ['11670bbab52858fbc38a1a6dbc021dab2f819df7866a9bf9cea9d51f35a2823d']),
    ('sql/migration_nov_fixes.sql', '', []),
]
BACKUP = "_backup_apply_nov_fixes"
NEXT = "run sql/migration_nov_fixes.sql in Supabase, restart python wsgi.py (Ctrl+F5 in the browser), test, then commit and push."

def sha(data):
    return hashlib.sha256(data).hexdigest()

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.isfile(os.path.join(root, "app", "__init__.py")) or not os.path.isfile(os.path.join(root, "wsgi.py")):
        sys.exit("Stopped: put this file in the Crescopus project folder (next to wsgi.py and the app folder), then run it again.")

    # Safety check first: never overwrite local changes we don't know about.
    clashes = []
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        new = base64.b64decode(b64)
        if not os.path.exists(path):
            if expected:
                clashes.append(rel + " (missing)")
            continue
        with open(path, "rb") as fh:
            current = fh.read()
        current_norm = current.replace(b"\r\n", b"\n")
        if current == new or current_norm == new:
            continue
        if not expected or sha(current_norm) not in expected:
            clashes.append(rel)
    if clashes:
        print("Stopped - nothing written. These files differ from the version this update was built from:")
        for c in clashes:
            print("   " + c)
        sys.exit("Push or share your latest changes and ask for the update to be rebuilt.")

    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64, expected in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                current = fh.read()
            if current == data or current.replace(b"\r\n", b"\n") == data:
                print("same     " + rel)
                continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
